# --- 다섯을 한 번에 찍는다 ---

@GetMapping("/me")
@ResponseBody
public String me(Authentication authentication,
        Principal principal,
        @AuthenticationPrincipal CustomUserDetails user,
        @AuthenticationPrincipal Object raw,
        @CurrentSecurityContext SecurityContext context) {
    System.out.println(">>> Authentication = " + authentication);
    System.out.println(">>> Principal      = " + principal);
    System.out.println(">>> Principal(T)   = " + user);
    System.out.println(">>> Principal(Obj) = " + raw
            + " (" + (raw == null ? "-" : raw.getClass().getSimpleName()) + ")");
    System.out.println(">>> Context        = " + context.getAuthentication());
    System.out.println(">>> Holder         = "
            + SecurityContextHolder.getContext().getAuthentication());
    return "ok";
}

#   로그인한 채로
$ curl -s -b user.txt localhost:8080/me

>>> Authentication = UsernamePasswordAuthenticationToken [Principal=
     CustomUserDetails [username=user@a.com], Granted Authorities=[ROLE_USER]]
>>> Principal      = UsernamePasswordAuthenticationToken [...]
>>> Principal(T)   = CustomUserDetails [username=user@a.com]
>>> Principal(Obj) = CustomUserDetails [...] (CustomUserDetails)
>>> Context        = UsernamePasswordAuthenticationToken [...]
>>> Holder         = UsernamePasswordAuthenticationToken [...]

#   Principal 파라미터는 토큰 자체다

#   Authentication 이 Principal 을 상속해서다 (4.1절)

#   로그인 안 한 채로 (permitAll 인 경로에서)
$ curl -s localhost:8080/me-public

>>> Authentication = AnonymousAuthenticationToken [Principal=anonymousUser]
>>> Principal      = null
>>> Principal(T)   = null
>>> Principal(Obj) = anonymousUser (String)
>>> Context        = AnonymousAuthenticationToken [...]
>>> Holder         = AnonymousAuthenticationToken [...]

#   Principal 만 null 이다

#   9.4절의 그 규격 차이가 여기까지 온다

#   Principal(T) 는 타입이 안 맞아 null 이다

# --- 그냥 쓰면 터진다 ---

@GetMapping("/me-public")
@ResponseBody
public String mePublic(@AuthenticationPrincipal CustomUserDetails user) {
    return user.getUsername();
}

